function renderStats(){const done=lessons.filter(l=>state.done.includes(l.id)).length,secs=state.sessions.reduce((a,s)=>a+(s.seconds||0),0),today=state.daily[dayKey()]||0,scored=state.sessions.filter(s=>s.score!==null&&s.score!==undefined);set("streak",state.streak);set("streak2",state.streak);set("doneCount",done);set("quizBest",state.best?state.best+"/10":"—");set("cardCount",state.knownCards.length);set("progressPercent",Math.round(done/84*100)+"%");document.getElementById("overallBar").style.width=(done/84*100)+"%";set("progressLine",done+" leçon(s) terminée(s) sur 84");document.getElementById("dailyBar").style.width=Math.min(100,today/900*100)+"%";set("dailyText",fmtTime(today)+" / 15 min aujourd'hui");set("dailyPercent",Math.min(100,Math.round(today/900*100))+"%");set("totalMinutes",Math.floor(secs/60));set("avgScore",scored.length?Math.round(scored.reduce((a,s)=>a+s.score,0)/scored.length)+"%":"—");set("sessionCount",groupCardSessions(state.sessions).length);set("knownTotal",state.knownCards.length);set("attemptTotal",state.attempts.length);renderWeekly();renderHistory();renderWeaknesses();renderErrorDiagnostics();renderAdaptiveDashboard();renderDistinctions();renderOralStats()}
function renderWeekly(){const el=document.getElementById("weeklyChart");if(!el)return;let ds=[];for(let i=6;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);ds.push({l:["dim","lun","mar","mer","jeu","ven","sam"][d.getDay()],m:Math.round((state.daily[dayKey(d)]||0)/60)})}let max=Math.max(15,...ds.map(x=>x.m));el.innerHTML=ds.map(x=>"<div class='chart-day'><div class='chart-track'><i style='height:"+(x.m/max*100)+"%'></i></div><b>"+x.m+"</b><small>"+x.l+"</small></div>").join("")}
