function renderHistory(){const el=document.getElementById("historyList");if(!el)return;const items=groupCardSessions(state.sessions).slice(0,30);el.innerHTML=items.length?items.map(s=>"<div class='history-item'><div class='history-icon'>"+(s.type==="Quiz"?"✧":s.type==="Leçon"?"▤":"▣")+"</div><div class='history-main'><b>"+esc(s.title)+"</b><small>"+s.date+" · "+(s.cardCount?s.cardCount+" fiche(s)":s.type)+(s.legacy?" · import V2":"")+"</small></div><div class='history-result'><b>"+fmtTime(s.seconds)+"</b><small>"+(s.score===null?"Temps réel":s.score+"%")+"</small></div></div>").join(""):"<p class='empty'>Ton historique apparaîtra après ta première activité.</p>"}
function adaptiveStats(){
 const map=new Map();
 for(const a of state.attempts){if(typeof a.correct!=="boolean")continue;const l=lessons.find(l=>l.title===a.lesson);if(!l)continue;let v=map.get(l.id);if(!v){v={lesson:l,total:0,errors:0,recent:[],questions:new Map()};map.set(l.id,v)}if(v.recent.length>=12)continue;v.total++;v.errors+=a.correct?0:1;v.recent.push(a.correct);if(!v.questions.has(a.question))v.questions.set(a.question,a.correct)}
 return [...map.values()].map(v=>({...v,accuracy:Math.round(100*(v.total-v.errors)/v.total),priority:v.recent.reduce((sum,ok,i)=>sum+(ok?-1:2)*Math.pow(.82,i),0)})).sort((a,b)=>b.priority-a.priority);
}
function renderWeaknesses(){const el=document.getElementById("weakList");if(!el)return;const stats=adaptiveStats(),weak=stats.filter(v=>v.priority>0).slice(0,5);el.innerHTML=weak.length?weak.map(v=>'<div class="history-item"><div class="history-main"><b>'+esc(v.lesson.title)+'</b><small>'+v.errors+' erreur(s) sur '+v.total+' réponses récentes'+(v.total<3?' · estimation provisoire':'')+'</small></div><div class="history-result"><b>'+v.accuracy+'%</b><button class="secondary" onclick="openLesson('+(v.lesson.day-1)+')">Revoir</button></div></div>').join("")+'<button class="primary full" onclick="showScreen(\'practice\')">Quiz ciblé</button>': '<p class="muted">'+(stats.length?'Aucun point faible prioritaire détecté.':'Réponds à des exercices pour obtenir une analyse personnalisée.')+'</p>'}

