let lessonResults=[], lessonQuestions=[];
function originalLessonQuestions(l,x){
 const make=(question,correct,wrong,explanation,offset)=>{const options=[...wrong];options.splice((l.day+offset)%3,0,correct);return {question,options,answer:(l.day+offset)%3,explanation}};
 const others=[lessonExtras[(l.day+12)%84],lessonExtras[(l.day+36)%84]];
 const [word,meaning]=x[2].split("|");
 return [{question:l.question,options:l.options,answer:l.answer,explanation:l.rule},
 make("Traduis : "+l.example,l.translation,others.map(y=>y[1]),l.translation,1),
 {kind:"vocab",question:"Écris en espagnol : "+meaning,options:[word],answer:0,explanation:word+" = "+meaning},
 make("Quelle phrase signifie : "+x[1]+" ?",x[0],others.map(y=>y[0]),x[0]+" = "+x[1],0),
 make("Écoute la phrase puis choisis sa traduction.",x[1],others.map(y=>y[1]),x[0]+" = "+x[1],1)];
}
