 let pool=shuffleAdaptive(lessons.flatMap(l=>(mode==="listening"?beginnerCourseQuestions(l).filter(q=>q.audio):buildLessonQuestions(l,lessonExtras[l.day-1])).map(q=>({...q,title:l.title,key:l.id+"|"+q.question+(q.audio?"|"+q.audio:""),targeted:mode==="errors"?unresolvedExercise({...q,title:l.title}):mode!=="random"&&weak.has(l.id)}))));
