 if(trainingMode(mode)){const allowed={grammar:["choice","gap"],vocabulary:["match","vocab","choice"],writing:["translation","order"],listening:["choice","dictation"],errors:["choice","gap","translation","order","dictation","match","vocab"]}[mode];pool=pool.filter(q=>allowed.includes(q.kind||"choice")&&(mode!=="grammar"||q.kind||q.question===lessons.find(l=>l.title===q.title)?.question)&&(mode!=="vocabulary"||q.kind||q.question.startsWith("Que signifie"))&&(mode!=="errors"||unresolvedExercise(q)));if(!pool.length){document.getElementById("quizArea").innerHTML='<div class="panel"><p>Aucune difficulté prioritaire détectée. Continue ton apprentissage.</p><button class="secondary full" onclick="showScreen(\'training\')">Retour à l’entraînement</button></div>';return}}
 const rank=(a,b)=>Number(last.has(a.key))-Number(last.has(b.key))||(counts.get(a.key)||0)-(counts.get(b.key)||0)||(!trainingMode(mode)?Math.abs(lessons.find(l=>l.title===a.title).week-adaptiveBeginnerBand().week)-Math.abs(lessons.find(l=>l.title===b.title).week-adaptiveBeginnerBand().week):0);
 const chosen=[],questions=new Set(),usedLessons=new Set();
