const immersionScenarios=MarabouPedagogy.scenarios;let immersionRun=null;
function openImmersion(){immersionRun=null;showScreen("immersion")}
function startImmersion(i){immersionRun=MarabouPedagogy.start(i);renderImmersion()}
function speakImmersion(i){const m=immersionRun?.messages[i];if(m)speak(m.text)}
function renderImmersion(){const el=document.getElementById("immersionContent");if(!el)return;const r=immersionRun;if(!r){el.innerHTML='<div class="immersion-grid">'+immersionScenarios.map((s,i)=>'<button class="immersion-tile" onclick="startImmersion('+i+')"><small>'+esc(s[1])+' · A1–A2</small><strong>'+esc(s[2])+'</strong><span>'+esc(s[4])+'</span><small>6 parcours possibles</small></button>').join("")+'</div>';return}const s=immersionScenarios[r.index],chat=r.messages.map((m,i)=>'<div class="immersion-bubble '+(m.role==="you"?"you":"npc")+'"><small>'+esc(m.role==="you"?"Tú":s[5])+'</small><p>'+esc(m.text)+'</p><button class="secondary immersion-audio" onclick="speakImmersion('+i+')">Écouter</button></div>').join("");el.innerHTML='<div class="immersion-heading"><h2>'+esc(s[2])+'</h2><p>'+esc(s[4])+'</p></div><div class="immersion-chat">'+chat+'</div><div class="panel">'+(r.finished?'<h2>Conversation terminée</h2><p>'+r.score+'/3 réponses adaptées.</p><button class="primary full" onclick="startImmersion('+r.index+')">Explorer un autre parcours</button><button class="secondary full" onclick="openImmersion()">Autres missions</button>':'<p class="eyebrow">ÉCHANGE '+(r.step+1)+'/3</p><p>'+esc(r.feedback)+'</p>'+r.order.map(i=>'<button class="secondary full immersion-choice" onclick="answerImmersion('+i+')">'+esc(MarabouPedagogy.choices(r)[i])+'</button>').join(""))+'</div>'}
function answerImmersion(i){const r=immersionRun;if(!r)return;const s=immersionScenarios[r.index],result=MarabouPedagogy.advance(r,i);if(!result)return;state.attempts.unshift({date:dayKey(),lesson:"Immersion : "+s[2],question:result.node,selected:result.selected,answer:result.expected,correct:result.ok,format:"immersion"});if(r.finished)record("Immersion",s[2],(Date.now()-r.started)/1000,Math.round(r.score/3*100),{scenarioId:s[0],branch:r.branch});else save();renderImmersion()}

function exerciseIdentity(q,title){return JSON.stringify([title||q.title||q.topic,q.kind||"choice",q.kind==="dictation"||q.kind==="match"?q.options[q.answer]:q.question])}
function attemptIdentity(a){return a.exerciseId||JSON.stringify([a.lesson,a.format||"choice",["dictation","match"].includes(a.format)?a.answer:a.question])}
function unresolvedExercise(q){const key=exerciseIdentity(q);const a=state.attempts.find(a=>attemptIdentity(a)===key);return !!a&&!a.correct}
function accentlessExercise(s){return normalizeExercise(s).normalize("NFD").replace(/\u0301|\u0308/g,"").normalize("NFC")}
function acceptedExercise(q,selected,correct){
 const n=normalizeExercise(selected),c=normalizeExercise(correct);if(n===c)return true;
 if(q.kind!=="translation")return false;
 // Explicitly equivalent subject pronouns only for unambiguous first-person examples.
 const alternatives={"ayer perdí el tren":["yo ayer perdí el tren","ayer yo perdí el tren","perdí el tren ayer"],"trabajo para ahorrar dinero":["yo trabajo para ahorrar dinero"],"hace dos años cambié de trabajo":["cambié de trabajo hace dos años"],"nunca he probado este plato":["no he probado nunca este plato","no he probado este plato nunca"],"llevo dos meses estudiando español":["llevo estudiando español dos meses","estudio español desde hace dos meses"]};
 return (alternatives[c]||[]).includes(n)
}
function exerciseCategory(q,selected,correct){
 if(normalizeExercise(selected)!==normalizeExercise(correct)&&accentlessExercise(selected)===accentlessExercise(correct))return "Accents et orthographe";
 if(q.kind==="match"||q.kind==="vocab"||String(q.question).startsWith("Que signifie"))return "Vocabulaire";
 if(q.kind==="dictation")return "Dictée";
 if(q.kind==="order")return "Ordre des mots";
 if(q.kind==="translation")return "Traduction";
 const rule=(q.rule||"")+" "+(q.topic||"");
 if(/subjonctif|subjuntivo/i.test(rule))return "Subjonctif";
 if(/préposition|por et para|por y para/i.test(rule))return "Prépositions";
 if(/accord|adjectif|singulier|pluriel/i.test(rule))return "Accords";
 if(/pronom|article/i.test(rule))return "Pronoms et articles";
 if(/connecteur|opposition|conséquence|reformulation|synthèse/i.test(rule))return "Connecteurs";
 if(/verbe|conditionnel|futur|passé|imparfait|indefinido|imperativo|impératif|participe|gérondif/i.test(rule))return "Conjugaison";
 return "Notion de la leçon"
}
function exerciseExplanation(q,selected,correct,ok){
 const category=exerciseCategory(q,selected,correct),rule=q.rule||q.explanation||"",example=q.example&&q.translation?" Exemple : "+q.example+" — "+q.translation:"";
 if(!ok&&category==="Accents et orthographe")return "Les lettres correspondent, mais les accents diffèrent. Écris exactement « "+correct+" ». Les accents peuvent modifier le sens ou la forme verbale."+example;
 if(q.kind==="match")return "Associations attendues : "+q.pairs.map(p=>p.join(" = ")).join(" ; ")+".";
 if(q.kind==="vocab")return "Vocabulaire : "+q.explanation+".";
 if(q.kind==="dictation")return "Transcription : "+correct+". "+(q.explanation||"")+" Réécoute en repérant les mots et les terminaisons."+example;
 if(q.kind==="order")return "Ordre attendu : "+correct+". "+q.explanation+". "+rule;
 if(q.kind==="translation")return "Traduction de référence : "+correct+". "+rule+example+(!ok?" Une autre formulation valide peut ne pas être reconnue par la correction locale.":"");
 return "Notion : "+category+". "+rule+example+(!ok?" Compare « "+selected+" » à « "+correct+" » dans ce contexte.":"");
}
function renderErrorDiagnostics(){
 const host=document.getElementById("weakList");if(!host)return;
 const recent=new Map();for(const a of state.attempts){if(!a||typeof a.correct!=="boolean")continue;const k=attemptIdentity(a);if(!recent.has(k))recent.set(k,a)}
 const errors=[...recent.values()].filter(a=>!a.correct&&lessons.some(l=>l.title===a.lesson)),groups=new Map();
 for(const a of errors){const category=a.category||"À reclasser";groups.set(category,(groups.get(category)||0)+1)}
 const list=[...groups].sort((a,b)=>b[1]-a[1]);
 const html='<div class="error-diagnostics"><h3>Erreurs à retravailler</h3><p class="muted">'+errors.length+' exercice(s) dont la dernière réponse est incorrecte.</p>'+list.map(([c,n])=>'<p><b>'+esc(c)+'</b> · '+n+'</p>').join("")+errors.slice(0,8).map(a=>'<details><summary>'+esc(a.question)+'</summary><p>Ta réponse : '+esc(String(a.selected||""))+'</p><p>Attendu : '+esc(String(a.answer||""))+'</p><p>'+esc(a.explanation||"Ancienne tentative : revois la notion dans la leçon.")+'</p></details>').join("")+(errors.length?'<button class="secondary full" onclick="showScreen(\'practice\',\'errors\')">Reprendre mes erreurs</button>':'')+'</div>';
 let el=document.getElementById("errorDiagnostics");if(!el){el=document.createElement("div");el.id="errorDiagnostics";host.after(el)}el.innerHTML=html;
}

function beginnerQuestions(l){const i=l.day-1,r=beginnerRows[i],same=beginnerRows.filter((x,j)=>j!==i&&x[2]!==r[2]);const others=same.filter((x,j)=>j%7===i%7);const choices=(question,correct,wrong)=>({question,options:[correct,...wrong],answer:0,rule:l.rule,example:l.example,translation:l.translation,topic:l.title,lessonId:l.id,explanation:l.translation});const q=choices(l.question,l.options[0],l.options.slice(1));const translation=choices("Que signifie « "+l.example+" » ?",l.translation,[others[0][2],others[1][2]]);const vocab=choices("Que signifie « "+r[3]+" » ?",r[4],[others[0][4],others[1][4]].filter((v,j,a)=>v!==r[4]&&a.indexOf(v)===j));const written={...choices("Traduis en espagnol : "+l.translation,l.example,[]),kind:"translation"};const dictation={...choices("Écoute et retranscris la phrase en espagnol.",l.example,[]),kind:"dictation",audio:l.example};return [q,translation,vocab,written,dictation].map(x=>({...x,options:[...new Set(x.options)]}));}

function beginnerRule(i,example,translation,question,correct){const rules=["Les salutations et les présentations utilisent des expressions courtes. Soy exprime l’identité, tengo l’âge et vivo le lieu de résidence.","El et los sont masculins ; la et las sont féminins. Les adjectifs s’accordent avec le nom. Mi et tu indiquent la possession.","Au présent, les verbes réguliers en -ar prennent -o, -as, -a ; en -er : -o, -es, -e ; en -ir : -o, -es, -e. No précède le verbe.","Gustar s’accorde avec ce qui plaît : gusta au singulier, gustan au pluriel. Quiero exprime une volonté ; por favor rend la demande polie.","Estar situe un lieu ; hay indique son existence. Ir est irrégulier : voy, vas, va, vamos. A + el devient al.","Les adjectifs de couleur s’accordent généralement avec le nom. Poder + infinitif exprime une possibilité ; tener que + infinitif une obligation ; ir a + infinitif un projet.","Les verbes irréguliers peuvent changer de radical : juego, prefiero, quiero. Más + adjectif + que permet de comparer.","Estar décrit notamment un état. Doler s’accorde avec la partie du corps : duele au singulier, duelen au pluriel. Deber + infinitif exprime un conseil ou une obligation.","Haber + participe forme le passé composé. Le passé simple situe une action terminée : trabajé, comí, viví. Fui est le passé simple de ir et ser.","L’imparfait décrit une habitude ou un contexte passé. Porque introduit une cause, pero une opposition. Lo et la remplacent un objet direct, le un destinataire.","Pour les voyages, les expressions courtes permettent de demander un service. Podría est une demande au conditionnel ; ir a + infinitif exprime un projet.","Creo que introduit une opinion. Le futur simple ajoute notamment -é à l’infinitif ; gustaría exprime un souhait. Si + présent exprime une condition réelle ; para + infinitif un but."];return rules[Math.floor(i/7)]+" Dans cet exercice, « "+correct+" » correspond à la forme ou au sens attendu."}

function beginnerCourseQuestions(l){const r=beginnerRows[l.day-1],base=beginnerQuestions(l),near=beginnerRows.filter((x,i)=>i!==l.day-1&&Math.floor(i/7)===l.week-1),unique=(values)=>[...new Map(values.map(v=>[normalizeExercise(v),v])).values()];const make=(question,correct,wrong,extra={})=>({...base[0],question,options:unique([correct,...wrong]).slice(0,3),answer:0,...extra});const vocab=make("Comment dit-on « "+r[4]+" » en espagnol ?",r[3],near.map(x=>x[3]));const audioRow=near.find(x=>x[1]!==r[1]);const audio=make("Écoute et choisis la traduction française.",audioRow[2],near.filter(x=>x!==audioRow).map(x=>x[2]),{audio:audioRow[1],example:audioRow[1],translation:audioRow[2],rule:"Écoute les mots et identifie le sens de la phrase.",explanation:audioRow[2]});const meaning=make("Que signifie « "+r[1]+" » ?",r[2],near.map(x=>x[2]));return [base[0],vocab,meaning,audio].filter((q,i,a)=>q.options.length>=2&&a.findIndex(v=>v.question===q.question)===i)}

function adaptiveBeginnerBand(){return MarabouPedagogy.band(lessons.filter(l=>state.done.includes(l.id)).length,state.attempts.filter(a=>a.format==="choice"&&lessons.some(l=>l.title===a.lesson)))}

/* V0.6 oral curriculum; stable dialogue IDs, no external service. */
function oralDialogs(){return [["Voyage","À l’hôtel","¿Tiene una reserva?","Sí, para dos noches.","¿A nombre de quién?","A nombre de García.","Combien de nuits ?","Deux","Trois","Une"],["Voyage","À l’aéroport","¿Dónde está la puerta doce?","Al final del pasillo.","¿Está lejos?","No, a cinco minutos.","Quelle porte ?","12","20","2"],["Voyage","Bagages","No encuentro mi maleta.","¿De qué color es?","Es negra.","Vamos a buscarla.","Couleur de la valise ?","Noire","Rouge","Bleue"],["Voyage","Réception","¿A qué hora es el desayuno?","De siete a diez.","¿Está incluido?","Sí, en el precio.","Le petit-déjeuner est-il inclus ?","Oui","Non","On ne sait pas"],["Voyage","Visite","¿Cuánto dura la visita?","Una hora y media.","¿Hay guía en francés?","Sí, a las once.","Durée ?","1 h 30","1 h","2 h"],["Restaurant","Commander","¿Qué desea tomar?","Una sopa y agua.","¿Algo más?","No, gracias.","Que commande le client ?","Soupe et eau","Salade et café","Riz et jus"],["Restaurant","Réserver","¿Tiene mesa para cuatro?","Sí, a las ocho.","Perfecto, gracias.","Hasta luego.","Nombre de personnes ?","Quatre","Deux","Six"],["Restaurant","Allergie","¿Lleva leche este plato?","No, lleva aceite.","Entonces lo quiero.","Muy bien.","Le plat contient-il du lait ?","Non","Oui","On ne sait pas"],["Restaurant","Addition","¿Nos trae la cuenta?","Claro, son veinte euros.","¿Puedo pagar con tarjeta?","Por supuesto.","Montant ?","20 €","12 €","30 €"],["Restaurant","Café","Un café con leche, por favor.","¿Grande o pequeño?","Pequeño.","Ahora mismo.","Taille du café ?","Petit","Grand","Moyen"],["Shopping","Pointure","¿Tiene estos zapatos en el cuarenta?","Sí, aquí están.","¿Puedo probármelos?","Claro.","Pointure ?","40","42","38"],["Shopping","Prix","¿Cuánto cuesta esta camisa?","Treinta euros.","¿Hay descuento?","Sí, cinco euros.","Remise ?","5 €","10 €","15 €"],["Shopping","Retour","Quiero devolver esta chaqueta.","¿Tiene el recibo?","Sí, aquí está.","De acuerdo.","Que demande le vendeur ?","Le reçu","La carte","Le passeport"],["Shopping","Couleur","Busco un pantalón azul.","Tenemos este modelo.","¿Hay uno negro?","Sí, también.","Autre couleur demandée ?","Noir","Vert","Blanc"],["Shopping","Marché","Quiero medio kilo de tomates.","¿Algo más?","Dos manzanas.","Son cuatro euros.","Combien de pommes ?","Deux","Quatre","Trois"],["Travail","Réunion","¿Cuándo empieza la reunión?","A las nueve.","¿En qué sala?","En la sala tres.","Heure ?","9 h","10 h","8 h"],["Travail","Télétravail","¿Trabajas mañana en casa?","Sí, por la mañana.","¿Y por la tarde?","Voy a la oficina.","Où travaille-t-il l’après-midi ?","Au bureau","Chez lui","Au café"],["Travail","Pause","¿Comemos juntos hoy?","Sí, a la una.","¿En el restaurante de siempre?","Perfecto.","Heure du déjeuner ?","13 h","12 h","14 h"],["Travail","Aide","¿Puedes ayudarme con este informe?","Sí, después de la reunión.","Muchas gracias.","De nada.","Quand ?","Après la réunion","Avant la réunion","Demain"],["Travail","Rendez-vous","¿Puedes venir el jueves?","No, tengo una cita.","¿Y el viernes?","Sí, sin problema.","Jour accepté ?","Vendredi","Jeudi","Lundi"],["Vie sociale","Invitation","¿Te apetece ir al cine?","Sí, esta noche.","¿A las siete?","Perfecto.","Activité ?","Cinéma","Football","Musée"],["Vie sociale","Sport","¿Qué haces los domingos?","Juego al fútbol.","¿Con tus amigos?","Sí, siempre.","Sport ?","Football","Tennis","Natation"],["Vie sociale","Présentation","¿De dónde eres?","Soy de Francia.","¿Vives aquí?","Sí, desde enero.","Depuis quand ?","Janvier","Mars","Juin"],["Vie sociale","Météo","Hace mucho frío hoy.","Sí, llevo una chaqueta.","¿Salimos mañana?","Si hace sol.","Condition pour sortir ?","Du soleil","De la pluie","Du vent"],["Vie sociale","Week-end","¿Qué hiciste ayer?","Visité un museo.","¿Te gustó?","Sí, mucho.","Activité d’hier ?","Musée","Cinéma","Shopping"],["Transports","Métro","¿Qué línea va al centro?","La línea dos.","¿Dónde cambio?","En Sol.","Ligne ?","2","3","5"],["Transports","Train","¿A qué hora sale el tren?","A las diez y cuarto.","¿De qué vía?","De la cinco.","Heure ?","10 h 15","10 h 30","9 h 15"],["Transports","Bus","¿Este autobús va al aeropuerto?","No, toma el número seis.","¿Dónde para?","Enfrente del banco.","Numéro du bus ?","6","9","3"],["Transports","Taxi","Lléveme al hotel, por favor.","¿Al hotel Central?","Sí, cerca de la estación.","De acuerdo.","Destination ?","Hôtel Central","Aéroport","Banque"],["Transports","À pied","¿Está lejos la plaza?","No, a diez minutos a pie.","¿Sigo recto?","Sí, y gira a la izquierda.","Direction finale ?","Gauche","Droite","Demi-tour"]]}
var oralRun;
function audioPrefs(){try{const p=JSON.parse(localStorage.getItem("marabouAudioPrefs")||"{}");return {rate:[.65,.85,1,1.15].includes(p.rate)?p.rate:.85,voice:typeof p.voice==="string"?p.voice:""}}catch(e){return {rate:.85,voice:""}}}
function changeAudioPrefs(){try{localStorage.setItem("marabouAudioPrefs",JSON.stringify({rate:Number(document.getElementById("oralRate").value),voice:document.getElementById("oralVoice").value}))}catch(e){}}
function renderAudioPrefs(){const el=document.getElementById("oralPrefs");if(!el)return;const p=audioPrefs(),voices=window.speechSynthesis?.getVoices().filter(v=>v.lang.startsWith("es"))||[];el.innerHTML='<h2>Lecteur audio</h2><label>Vitesse <select id="oralRate" onchange="changeAudioPrefs()">'+[.65,.85,1,1.15].map(v=>'<option value="'+v+'" '+(v===p.rate?"selected":"")+'>'+v+'×</option>').join("")+'</select></label><label> Voix <select id="oralVoice" onchange="changeAudioPrefs()"><option value="">Espagnol automatique</option>'+voices.map(v=>'<option value="'+esc(v.voiceURI)+'" '+(v.voiceURI===p.voice?"selected":"")+'>'+esc(v.name+" · "+v.lang)+'</option>').join("")+'</select></label><button class="secondary full" onclick="speak(\'Hola, ¿qué tal?\')">Tester la voix</button>'}
function openOral(){oralRun=null;showScreen("oral")}
function startOral(i){const d=oralDialogs()[i];if(!d)return;oralRun={i,started:Date.now(),step:0,score:0,answered:false,played:false,options:[],feedback:""};renderOral()}
function oralQuestions(d){return [{prompt:"Écoute le dialogue puis réponds : "+d[6],audio:d.slice(2,6).join(" … "),options:d.slice(7,10),correct:d[7]},{prompt:"Reconnais la première phrase prononcée.",audio:d[2],options:[d[2],d[3],d[4]],correct:d[2]},{prompt:"Quelle est la dernière réplique ?",audio:d[5],options:[d[5],d[2],d[3]],correct:d[5]}]}
function renderOral(){renderAudioPrefs();const el=document.getElementById("oralContent");if(!el)return;if(!oralRun){el.innerHTML='<div class="immersion-grid">'+oralDialogs().map((d,i)=>'<button class="immersion-tile" onclick="startOral('+i+')"><small>'+esc(d[0])+' · '+(i<15?"A1 consolidé":"A2")+'</small><strong>'+esc(d[1])+'</strong><span>3 QCM audio</span></button>').join("")+'</div>';return}const r=oralRun,d=oralDialogs()[r.i],qs=oralQuestions(d);if(r.step>=qs.length){el.innerHTML='<div class="panel"><h2>'+esc(d[1])+' · '+r.score+'/3</h2><p>Dialogue et répétition orale :</p>'+d.slice(2,6).map((line,i)=>'<p>'+esc(line)+' <button class="secondary" onclick="speakOralLine('+i+')">Écouter</button></p>').join("")+'<button class="primary full" onclick="startOral('+r.i+')">Rejouer</button><button class="secondary full" onclick="openOral()">Autres dialogues</button></div>';return}const q=qs[r.step];if(!r.options.length)r.options=shuffleAdaptive(q.options);el.innerHTML='<div class="panel"><p class="eyebrow">'+esc(d[0])+' · '+(r.step+1)+'/3</p><h2>'+esc(d[1])+'</h2><p>'+esc(q.prompt)+'</p><button class="primary full" onclick="playOral()">Écouter / réécouter</button><div class="answers">'+r.options.map((v,i)=>'<button class="answer" '+(!r.played||r.answered?"disabled":"")+' onclick="answerOral('+i+')">'+esc(v)+'</button>').join("")+'</div>'+(r.answered?'<div class="tip">'+esc(r.feedback)+'</div><button class="primary full" onclick="nextOral()">Continuer</button>':"")+'</div>'}
function playOral(){if(!oralRun||oralRun.step>=3)return;oralRun.played=true;speak(oralQuestions(oralDialogs()[oralRun.i])[oralRun.step].audio);renderOral()}
function speakOralLine(i){if(oralRun)speak(oralDialogs()[oralRun.i][i+2])}
function answerOral(i){const r=oralRun;if(!r||!r.played||r.answered||!r.options[i])return;const d=oralDialogs()[r.i],q=oralQuestions(d)[r.step],ok=r.options[i]===q.correct;r.answered=true;r.score+=Number(ok);r.feedback=(ok?"Bonne réponse. ":"Réponse attendue : "+q.correct+". ")+"Écoute : "+q.audio;state.attempts.unshift({date:dayKey(),lesson:"Oral : "+d[1],question:q.prompt,selected:r.options[i],answer:q.correct,correct:ok,format:"oral",category:"Compréhension orale",exerciseId:"oral-"+r.i+"-"+r.step});save();renderOral()}
function nextOral(){const r=oralRun;if(!r||!r.answered||r.step>=3)return;r.step++;r.answered=false;r.played=false;r.options=[];if(r.step===3)record("Oral",oralDialogs()[r.i][1],(Date.now()-r.started)/1000,Math.round(r.score/3*100),{dialogueId:"oral-"+r.i,skill:"Compréhension orale"});renderOral()}
function renderOralStats(){const el=document.getElementById("oralStats");if(!el)return;const a=state.attempts.filter(x=>x.format==="oral"),sessions=state.sessions.filter(x=>x.type==="Oral"),pct=x=>x.length?Math.round(x.filter(v=>v.correct).length/x.length*100)+" %":"—";el.innerHTML='<h2>Compétences orales</h2><p>Compréhension : '+pct(a)+'</p><p>Reconnaissance de phrases : '+pct(a.filter(x=>!x.exerciseId.endsWith("-0")))+'</p><p>Dialogues : '+new Set(sessions.map(x=>x.dialogueId)).size+'/30 · Temps de pratique : '+fmtTime(sessions.reduce((n,x)=>n+x.seconds,0))+'</p><p class="muted">La prononciation n’est pas évaluée automatiquement.</p>'}
function pedagogicalProfile(){return MarabouPedagogy.profile(lessons,state)}
if(window.speechSynthesis)window.speechSynthesis.addEventListener("voiceschanged",()=>{if(document.getElementById("oral")?.classList.contains("active"))renderAudioPrefs()});
